-- Staging vector post-load: read-only report for the operator and for independent validation (Kiro 3).
-- Run with: bash scripts/aws/staging-db-vector-postload.sh report --cluster vitana-aurora-staging
-- SELECT statements only. One statement per block, separated by a line that is exactly "-- ;;".
-- After the post-load, every column_type is vector(<dims>). After the embedding backfill, null_count matches
-- Supabase's NULLs for the column and stashed_still_null is 0.

SELECT 'ai_memory' AS table_name, 'embedding' AS column_name, (SELECT format_type(a.atttypid, a.atttypmod) FROM pg_attribute a WHERE a.attrelid = 'public.ai_memory'::regclass AND a.attname = 'embedding') AS column_type, (SELECT NOT a.attnotnull FROM pg_attribute a WHERE a.attrelid = 'public.ai_memory'::regclass AND a.attname = 'embedding') AS nullable, count(*) AS row_count, count(x.embedding) AS non_null, count(*) - count(x.embedding) AS null_count, (SELECT count(*) FROM migration_audit.vector_incomplete s WHERE s.table_name = 'ai_memory' AND s.column_name = 'embedding') AS stashed, (SELECT count(*) FROM migration_audit.vector_incomplete s JOIN public.ai_memory y ON y.id::text = s.pk WHERE s.table_name = 'ai_memory' AND s.column_name = 'embedding' AND y.embedding IS NULL) AS stashed_still_null FROM public.ai_memory x
UNION ALL SELECT 'calendar_events' AS table_name, 'embedding' AS column_name, (SELECT format_type(a.atttypid, a.atttypmod) FROM pg_attribute a WHERE a.attrelid = 'public.calendar_events'::regclass AND a.attname = 'embedding') AS column_type, (SELECT NOT a.attnotnull FROM pg_attribute a WHERE a.attrelid = 'public.calendar_events'::regclass AND a.attname = 'embedding') AS nullable, count(*) AS row_count, count(x.embedding) AS non_null, count(*) - count(x.embedding) AS null_count, (SELECT count(*) FROM migration_audit.vector_incomplete s WHERE s.table_name = 'calendar_events' AND s.column_name = 'embedding') AS stashed, (SELECT count(*) FROM migration_audit.vector_incomplete s JOIN public.calendar_events y ON y.id::text = s.pk WHERE s.table_name = 'calendar_events' AND s.column_name = 'embedding' AND y.embedding IS NULL) AS stashed_still_null FROM public.calendar_events x
