UNION ALL SELECT 'memory_facts' AS table_name, 'embedding' AS column_name, (SELECT format_type(a.atttypid, a.atttypmod) FROM pg_attribute a WHERE a.attrelid = 'public.memory_facts'::regclass AND a.attname = 'embedding') AS column_type, (SELECT NOT a.attnotnull FROM pg_attribute a WHERE a.attrelid = 'public.memory_facts'::regclass AND a.attname = 'embedding') AS nullable, count(*) AS row_count, count(x.embedding) AS non_null, count(*) - count(x.embedding) AS null_count, (SELECT count(*) FROM migration_audit.vector_incomplete s WHERE s.table_name = 'memory_facts' AND s.column_name = 'embedding') AS stashed, (SELECT count(*) FROM migration_audit.vector_incomplete s JOIN public.memory_facts y ON y.id::text = s.pk WHERE s.table_name = 'memory_facts' AND s.column_name = 'embedding' AND y.embedding IS NULL) AS stashed_still_null FROM public.memory_facts x
