UNION ALL SELECT 'user_intents' AS table_name, 'embedding_v2' AS column_name, (SELECT format_type(a.atttypid, a.atttypmod) FROM pg_attribute a WHERE a.attrelid = 'public.user_intents'::regclass AND a.attname = 'embedding_v2') AS column_type, (SELECT NOT a.attnotnull FROM pg_attribute a WHERE a.attrelid = 'public.user_intents'::regclass AND a.attname = 'embedding_v2') AS nullable, count(*) AS row_count, count(x.embedding_v2) AS non_null, count(*) - count(x.embedding_v2) AS null_count, (SELECT count(*) FROM migration_audit.vector_incomplete s WHERE s.table_name = 'user_intents' AND s.column_name = 'embedding_v2') AS stashed, (SELECT count(*) FROM migration_audit.vector_incomplete s JOIN public.user_intents y ON y.intent_id::text = s.pk WHERE s.table_name = 'user_intents' AND s.column_name = 'embedding_v2' AND y.embedding_v2 IS NULL) AS stashed_still_null FROM public.user_intents x
